package com.tripnest.security; import com.tripnest.repository.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.authentication.preauth.AbstractPreAuthenticatedProcessingFilter; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.stereotype.Component; import java.io.IOException; import java.util.*;
@Component public class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserRepository users; public JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain f)throws ServletException,IOException{String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")&&jwt.valid(h.substring(7))){users.findByEmail(jwt.email(h.substring(7))).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getEmail(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole())))));} f.doFilter(r,s);} }
